import { LitElement, html, nothing } from 'lit';
import { repeat } from 'lit/directives/repeat.js';
import { styles } from './components/styles.js';
import { groupHome, purposes, purposeMatches, purposeCapabilities, suggestedMeasurement, type Purpose } from './components/jobs.js';
import { accessState, usageLabel, requestExplanation, recordLabel } from './components/experience.js';
import { canShare, commandLabel, hasControl, kindLabel, readCapability, stateLabel,
  type ActionOption, type Job, type Member, type Operation, type Resource, type Status, type Summary } from './components/models.js';

class GenesisHome extends LitElement {
  static override properties = {
    status: { state: true }, catalog: { state: true }, summary: { state: true }, page: { state: true }, busy: { state: true },
    message: { state: true }, feedback: { state: true }, secret: { state: true }, name: { state: true }, selected: { state: true }, outcome: { state: true },
    search: { state: true }, domain: { state: true }, coverage: { state: true }, grantResources: { state: true },
    grantCapabilities: { state: true }, visibleCount: { state: true }, template: { state: true }, editMember: { state: true }, volumeLimit: { state: true },
    jobStep: { state: true }, jobPurpose: { state: true }, jobName: { state: true }, jobResource: { state: true }, jobHours: { state: true }, jobVolume: { state: true }, jobSearch: { state: true }, jobCreated: { state: true }, pairCode: { state: true }, pairExpiry: { state: true }, pairingJob: { state: true }, verifyingJob: { state: true }, jobCapabilities: { state: true },
    nativeEditId: { state: true }, editHours: { state: true }, editVolume: { state: true },
    openJobId: { state: true },
    jobIncludeResource: { state: true },
    jobBrowseAll: { state: true },
  };
  declare private status: Status | undefined;
  declare private catalog: Resource[]; declare private summary: Summary | undefined;
  declare private page: string; declare private busy: boolean; declare private message: string;
  declare private feedback: string; declare private secret: string; declare private name: string; declare private selected: string[];
  declare private outcome: Operation | undefined; declare private search: string; declare private domain: string;
  declare private coverage: string; declare private grantResources: string[]; declare private grantCapabilities: string[];
  declare private visibleCount: number; declare private template: string; declare private editMember: Member | undefined;
  declare private volumeLimit: string;
  private secretScope: { resources: Resource[]; capabilities: string[] } | undefined;
  private csrf = '';
  declare private jobStep: number; declare private jobPurpose: Purpose; declare private jobName: string; declare private jobResource: string;
  declare private jobHours: string; declare private jobVolume: string; declare private jobSearch: string; declare private jobCreated: string; declare private pairCode: string; declare private pairExpiry: string; declare private pairingJob: string; declare private verifyingJob: string;
  declare private jobCapabilities: string[]; private jobDraft = false; private sharingDraft = false; private verifyTimer: ReturnType<typeof setTimeout> | undefined; private verifyBaseline = '';
  private verificationIsReading = false;
  declare private nativeEditId: string; declare private editHours: string; declare private editVolume: string;
  declare private openJobId: string;
  declare private jobIncludeResource: boolean;
  declare private jobBrowseAll: boolean;
  private sharingReturnPage = 'access';
  private warnDraft = (event: BeforeUnloadEvent) => { if (this.jobDraft || this.sharingDraft) { event.preventDefault(); event.returnValue = ''; } };
  static override styles = styles;

  constructor() {
    super(); this.catalog = []; this.page = 'home'; this.busy = false; this.message = ''; this.feedback = ''; this.secret = ''; this.name = '';
    this.selected = []; this.search = ''; this.domain = ''; this.coverage = ''; this.grantResources = [];
    this.grantCapabilities = []; this.template = 'custom'; this.visibleCount = 100; this.volumeLimit = '';
    this.jobStep = 1; this.jobPurpose = 'observer'; this.jobName = 'Home observer'; this.jobResource = ''; this.jobHours = '24'; this.jobVolume = '40'; this.jobSearch = ''; this.jobCreated = ''; this.pairCode = ''; this.pairExpiry = ''; this.pairingJob = ''; this.verifyingJob = ''; this.jobCapabilities = [];
    this.nativeEditId = ''; this.editHours = '24'; this.editVolume = '';
    this.openJobId = '';
    this.jobIncludeResource = false;
    this.jobBrowseAll = false;
  }
  override connectedCallback() { super.connectedCallback(); window.addEventListener('beforeunload', this.warnDraft); void this.refresh(); }
  override disconnectedCallback() { super.disconnectedCallback(); window.removeEventListener('beforeunload', this.warnDraft); if (this.verifyTimer) clearTimeout(this.verifyTimer); }
  private async api(path: string, body?: unknown): Promise<any> {
    const response = await fetch(new URL(`api/${path}`, document.baseURI), { credentials: 'same-origin', cache: 'no-store',
      ...(body === undefined ? {} : { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-GM-CSRF': this.csrf }, body: JSON.stringify(body) }) });
    const value = await response.json();
    if (!response.ok && !value.commandState) throw new Error(value.error?.message ?? 'The home could not complete the request.');
    return value;
  }
  private async refresh() {
    this.busy = true; this.message = ''; this.feedback = '';
    try { const session = await this.api('session'); this.csrf = session.csrf; this.name = session.name; await this.load(); }
    catch (error) { this.message = error instanceof Error ? error.message : 'The home is unavailable.'; }
    finally { this.busy = false; }
  }
  private async load() {
    const catalog = await this.api('catalog'); this.catalog = catalog.resources; this.summary = catalog.summary;
    this.status = await this.api('status');
    if ((!this.status!.ready || this.status!.needsRecovery) && !this.sharingDraft) this.selected = this.status!.resources.map(r => r.id);
  }
  private async work(action: () => Promise<void>) {
    this.busy = true; this.message = ''; this.feedback = '';
    try { await action(); await this.load(); }
    catch (error) { this.message = error instanceof Error ? error.message : 'The home is unavailable. Review Activity before another request.'; }
    finally { this.busy = false; }
  }
  private navigate(page: string) { this.page = page; this.message = ''; this.feedback = ''; if (page === 'activity') void this.refresh(); }
  private beginSharing(returnPage = 'access') {
    if (!this.sharingDraft) { this.selected = this.status!.resources.map(r => r.id); this.search = ''; this.domain = ''; this.coverage = ''; }
    this.sharingReturnPage = returnPage; this.sharingDraft = true; this.navigate('setup');
  }
  private toggle(values: string[], id: string, checked: boolean) { return checked ? [...new Set([...values, id])] : values.filter(value => value !== id); }
  private filters() {
    return html`<div class="filters">
      <label class="field search">Find a device or entity<input type="search" .value=${this.search} placeholder="Search by name or type" @input=${(e: Event) => { this.search = (e.target as HTMLInputElement).value; }}></label>
      <label class="field">Device type<select aria-label="Device type" .value=${this.domain} @change=${(e: Event) => { this.domain = (e.target as HTMLSelectElement).value; }}><option value="">All types</option>${[...new Set(this.catalog.map(r => r.kind))].sort().map(kind => html`<option value=${kind}>${kindLabel(kind)}</option>`)}</select></label>
      <label class="field">Show<select aria-label="Show" .value=${this.coverage} @change=${(e: Event) => { this.coverage = (e.target as HTMLSelectElement).value; }}><option value="">Everything</option><option value="control">Can control</option><option value="read">Read only</option><option value="inventory">Inventory only</option><option value="shared">Shared through Mesh</option><option value="unavailable">Unavailable</option></select></label>
    </div>`;
  }
  private filteredResources() {
    const search = this.search.trim().toLocaleLowerCase(); const shared = new Set(this.status!.resources.map(r => r.id));
    return this.catalog.filter(r => (!this.domain || r.kind === this.domain) &&
      (!search || [r.name, r.entityId, r.deviceName ?? '', r.areaName ?? r.area ?? '', kindLabel(r.kind)].join(' ').toLocaleLowerCase().includes(search)) &&
      (!this.coverage || this.coverage === 'control' && hasControl(r) || this.coverage === 'read' && r.readable && !hasControl(r) ||
        this.coverage === 'inventory' && !canShare(r) || this.coverage === 'shared' && shared.has(r.id) || this.coverage === 'unavailable' && !r.available));
  }
  private inventoryPager(total: number) { return total > this.visibleCount ? html`<p class="hint">Showing ${this.visibleCount} of ${total} matches. Search or filter to narrow the list.</p><button type="button" @click=${() => { this.visibleCount += 100; }}>Show next 100 entities</button>` : nothing; }
  private selectMatching(add: boolean) {
    const matching = this.filteredResources().filter(canShare).map(resource => resource.id);
    if (!add) { this.selected = this.selected.filter(id => !matching.includes(id)); this.feedback = 'Matching resources were removed from this selection. Save to apply it.'; return; }
    const additions = matching.filter(id => !this.selected.includes(id));
    const capacity = Math.max(0, 256 - this.selected.length);
    this.selected = [...this.selected, ...additions.slice(0, capacity)];
    this.feedback = additions.length > capacity ? `Selected ${capacity} of ${additions.length} new matches. This preview can share 256 resources; narrow the filter or clear other selections.` : `${additions.length} matching resources added. Review the selection, then save to apply it.`;
  }
  private badges(resource: Resource, shared = false) {
    return html`<div class="badges"><span class="badge">${kindLabel(resource.kind)}</span><span class="badge ${canShare(resource) ? '' : 'muted'}">${hasControl(resource) ? 'Control available' : resource.readable ? 'Read only' : 'Inventory only'}</span>
      ${shared ? html`<span class="badge">Shared through Mesh</span>` : nothing}${!resource.available ? html`<span class="badge warning">${resource.state === 'unknown' ? 'State unknown' : 'Unavailable'}</span>` : nothing}</div>`;
  }
  private inventorySummary() {
    return html`<div class="metrics"><div class="metric"><strong>${this.summary?.total ?? this.catalog.length}</strong><span>entities discovered</span></div><div class="metric"><strong>${this.summary?.controllable ?? this.catalog.filter(hasControl).length}</strong><span>with controls</span></div><div class="metric"><strong>${this.summary?.readable ?? this.catalog.filter(r => r.readable).length}</strong><span>can be observed</span></div></div>`;
  }
  private setup() {
    const filtered = this.filteredResources(); const heating = this.catalog.some(r => this.selected.includes(r.id) && r.kind === 'climate');
    return html`<p class="eyebrow">1 · Choose what can be shared</p><h1>Your whole home, in view.</h1><p class="page-description">Browse everything Home Assistant exposes. Choose which entities may be used through Genesis Mesh. Sensors can provide observations; supported controls can accept bounded requests.</p>
      ${this.status?.needsRecovery ? html`<p class="notice">Review sharing to finish this update. Check the selected resources and save. Existing keys and client credentials are preserved; participant access is not broadened automatically.</p>` : nothing}${this.inventorySummary()}
      <form @submit=${(event: Event) => { event.preventDefault(); const data = new FormData(event.currentTarget as HTMLFormElement); void this.work(async () => { await this.api('setup', { resources: this.selected, minimum: Number(data.get('minimum') ?? this.status!.minimum), maximum: Number(data.get('maximum') ?? this.status!.maximum) }); this.sharingDraft = false; this.navigate(this.sharingReturnPage); }); }}>
        ${this.filters()}<section class="card"><div class="row"><h2>Choose what to share</h2><span class="count">${this.selected.length} selected</span></div><p class="hint">New discoveries stay unshared. Existing access profiles keep their current scope.</p><div class="actions"><button type="button" ?disabled=${this.busy || this.selected.length >= 256} @click=${() => this.selectMatching(true)}>Select matching shareable items</button><button type="button" ?disabled=${this.busy || !this.selected.length} @click=${() => this.selectMatching(false)}>Clear matching selection</button></div>
          ${filtered.length ? filtered.slice(0, this.visibleCount).map(r => html`<label class="pick ${canShare(r) ? '' : 'disabled'}"><input type="checkbox" aria-label=${`Share ${r.name}`} .checked=${this.selected.includes(r.id)} ?disabled=${this.busy || !canShare(r) || this.selected.length >= 256 && !this.selected.includes(r.id)} @change=${(e: Event) => { this.selected = this.toggle(this.selected, r.id, (e.target as HTMLInputElement).checked); }}><span><strong>${r.name}</strong>${r.area ? html`<br><small>${r.area}</small>` : nothing}${this.badges(r)}${r.reason ? html`<small>${r.reason}</small>` : nothing}</span></label>`) : html`<p class="empty">No matches. Try another name or type.</p>`}
          <p class="hint">Showing ${Math.min(filtered.length, this.visibleCount)} of ${filtered.length} matching entities, from ${this.catalog.length} entities. A physical device may have several entities. Up to 256 can be shared.</p>${this.inventoryPager(filtered.length)}</section>
        ${heating ? html`<section class="card"><h2>Heating limits</h2><p>Delegated Celsius setpoints must stay inside these bounds and the device’s own limits.</p><div class="ranges"><label class="field">Minimum °C<input name="minimum" type="number" min="10" max="35" step="0.5" .value=${String(this.status?.minimum ?? 19)} required></label><label class="field">Maximum °C<input name="maximum" type="number" min="10" max="35" step="0.5" .value=${String(this.status?.maximum ?? 23)} required></label></div></section>` : nothing}
        <button class="primary" ?disabled=${this.busy || !this.selected.length}>Save sharing selection</button>${this.status!.ready ? html`<button type="button" ?disabled=${this.busy} @click=${() => this.navigate('devices')}>Cancel</button>` : nothing}<p class="hint">Saving makes these resources available for explicit access profiles. It does not operate a device or grant new permissions to an existing participant.</p>
      </form>`;
  }
  private devices() {
    const filtered = this.filteredResources(); const shared = new Set(this.status!.resources.map(r => r.id));
    return html`<div class="row"><div><p class="eyebrow">Your devices & entities</p><h1>See where everything fits.</h1></div><div class="actions"><button ?disabled=${this.busy} @click=${() => { void this.refresh(); }}>Refresh devices</button><button class="primary" ?disabled=${this.busy} @click=${() => this.beginSharing()}>Change shared devices</button></div></div><p class="page-description">Every discovered entity type appears here. Sharing and access are separate: a participant needs both selected resources and permitted operations.</p>${this.inventorySummary()}${this.filters()}<p class="count">${filtered.length} matching entities · ${shared.size} shared</p>
      <div class="inventory-list">${groupHome(filtered.slice(0, this.visibleCount)).map(room => html`<section class="room"><h2>${room.name}</h2>${room.devices.map(device => html`<section class="device-group">${device.resources.length > 1 ? html`<h3>${device.name}</h3>` : nothing}${repeat(device.resources, r => r.id, r => html`<article class="card"><div class="row"><h2 class="device-title">${r.name}</h2><span>${stateLabel(r.state)}</span></div>${r.areaName || r.area || r.deviceName ? html`<p class="hint">${[r.areaName || r.area, r.deviceName].filter(Boolean).join(' · ')}</p>` : nothing}${this.badges(r, shared.has(r.id))}${r.reason ? html`<p class="hint">${r.reason}</p>` : nothing}
        ${shared.has(r.id) ? this.deviceRequests(r) : html`<p class="hint">Not shared through Mesh. ${canShare(r) ? 'Choose Change shared devices to make it available for access profiles.' : 'Its current adapter does not offer delegated reads or controls.'}</p>`}<details><summary>Entity reference</summary><code>${r.entityId}</code><p class="hint">Discovery does not enroll the physical device as a Genesis Mesh node.</p></details></article>`)}</section>`)}</section>`)}</div>${this.inventoryPager(filtered.length)}${!filtered.length ? html`<p class="empty">No matches. Clear a filter to see more of your home.</p>` : nothing}`;
  }
  private deviceRequests(resource: Resource) {
    return html`<details><summary>Try a request as ${this.name}</summary><p class="hint">Read requests observe state. Control requests below operate this device and use your current administrator identity.</p>
      ${resource.operations.map(op => html`<section class="operation"><h3>${op.label}</h3><form @submit=${(event: Event) => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; if (!form.reportValidity()) return; const data = new FormData(form); const parameters: Record<string, string | number> = {}; for (const parameter of op.parameters) { const value = String(data.get(parameter.name) ?? '').trim(); if (!value) { this.message = 'Choose each requested value before sending a control request.'; return; } parameters[parameter.name] = parameter.type === 'number' ? Number(value) : value; } this.run(resource, op, parameters); }}>
        ${op.parameters.map(parameter => html`<label class="field">${parameter.label}${parameter.type === 'number' ? html`<input aria-label=${parameter.label} name=${parameter.name} type="number" min=${op.capability === 'ha.climate.set_temperature' ? Math.max(parameter.minimum ?? -50, this.status!.minimum) : parameter.minimum ?? nothing} max=${op.capability === 'ha.climate.set_temperature' ? Math.min(parameter.maximum ?? 60, this.status!.maximum) : parameter.maximum ?? nothing} step=${parameter.step ?? 'any'} placeholder="Choose a value" required>` : html`<select aria-label=${parameter.label} name=${parameter.name} required><option value="" disabled selected>Choose an option</option>${parameter.options?.map(option => html`<option value=${option}>${stateLabel(option)}</option>`)}</select>`}</label>`)}
        <button ?disabled=${this.busy || op.capability !== readCapability && !resource.available}>${op.capability === readCapability ? 'Observe current state' : `Request ${op.label.toLocaleLowerCase()}`}</button></form></section>`)}
    </details>`;
  }
  private run(resource: Resource, operation: ActionOption, parameters: Record<string, string | number>) {
    void this.work(async () => { this.outcome = await this.api('actions', { requestId: crypto.randomUUID(), resourceId: resource.id, expiresAt: new Date(Date.now() + 60000).toISOString(), capability: operation.capability, parameters }); });
  }
  private operationChoices(): ActionOption[] {
    const choices = new Map<string, ActionOption>(); for (const resource of this.status!.resources.filter(r => this.grantResources.includes(r.id))) for (const op of resource.operations) choices.set(op.capability, op);
    return [...choices.values()].sort((a, b) => a.capability === readCapability ? -1 : b.capability === readCapability ? 1 : a.label.localeCompare(b.label));
  }
  private chooseTemplate(template: string) {
    this.template = template; this.grantCapabilities = template === 'custom' ? [] : this.operationChoices().filter(op => op.capability === readCapability || template === 'lighting' && op.capability.startsWith('ha.light.') || template === 'media' && op.capability.startsWith('ha.media.')).map(op => op.capability);
    if (this.grantCapabilities.includes('ha.media.volume') && !this.volumeLimit) this.volumeLimit = '40';
  }
  private cancelEdit() { this.editMember = undefined; this.grantResources = []; this.grantCapabilities = []; this.template = 'custom'; this.volumeLimit = ''; }
  private beginEdit(member: Member) {
    this.secret = ''; this.editMember = member; this.grantResources = [...member.resources]; this.grantCapabilities = [...member.capabilities]; this.template = 'custom';
    this.volumeLimit = member.capabilities.includes('ha.media.volume') ? String(member.limits?.maxVolumePct ?? 100) : '';
    void this.updateComplete.then(() => this.renderRoot.querySelector('form.access-form')?.scrollIntoView({ behavior: 'smooth', block: 'start' }));
  }
  private async copyCredential() {
    try {
      if (!navigator.clipboard) throw new Error('Clipboard unavailable');
      await navigator.clipboard.writeText(this.secret);
      this.feedback = 'Credential copied. Paste it only into this client’s secret storage.';
    } catch { this.message = 'Automatic copy is unavailable in this browser. Select and copy the private credential shown above.'; }
  }
  private async copyPairingCode() {
    if (!this.pairCode || Date.parse(this.pairExpiry) <= Date.now()) { this.feedback = 'This connection code has expired. Get a new code before pairing.'; return; }
    try { if (!navigator.clipboard) throw new Error('Clipboard unavailable'); await navigator.clipboard.writeText(this.pairCode); this.feedback = 'Connection code copied. Paste it into your Home Assistant integration setup.'; }
    catch { this.feedback = 'Automatic copy is unavailable here. Select the connection code above and copy it into your Home Assistant integration setup.'; }
  }
  private clientGuide(resources: Resource[], capabilities: string[]) {
    const baseUrl = this.status!.connectionGuide?.baseUrl ?? 'http://[internal-app-hostname]:8098';
    const readable = capabilities.includes(readCapability) ? resources.find(resource => resource.readable) : undefined;
    return html`<details><summary>Connect this service client</summary><ol><li>Use a trusted client that can reach the Home Assistant private app network. The credential belongs in that client’s secret storage.</li><li>List its permitted resources using the address below. This authenticates the client without operating a device.</li><li>Watch this profile’s last authenticated request, then review Activity for its observations or controls.</li></ol><p class="hint">Creating a profile grants permission. It does not pair a phone, install software, or prove a physical device’s identity. Direct phone joining and ordinary household-user sign-in are not available in this preview.</p><p>Private client address</p><code>${baseUrl}</code><p class="hint">This address works only from the HA app network. No public port or remote access is opened.${this.status!.connectionGuide?.baseUrl ? '' : ' Find the app hostname in HA app information and replace the placeholder.'}</p><p>First authenticated request</p><code>GET ${baseUrl}/v1/resources
Authorization: Bearer [your saved client credential]</code><p class="hint">The response lists only this profile’s resources and permitted operation names. A successful request updates its usage status; it does not mean the client remains online.</p>${resources.length ? html`<p>Selected resources</p><ul>${resources.map(resource => html`<li>${resource.name}<code>${resource.id}</code></li>`)}</ul>` : nothing}${readable ? html`<p>Then try a status observation. Your client supplies a fresh UUID and expiry for each request.</p><code>POST ${baseUrl}/v1/actions
Authorization: Bearer [your saved client credential]
Content-Type: application/json

${JSON.stringify({ requestId: '[fresh UUID v4]', resourceId: readable.id, capability: readCapability, parameters: {}, expiresAt: '[UTC time within the next two minutes]' }, null, 2)}</code>` : nothing}</details>`;
  }
  private accessCreated() {
    return html`<section class="notice success"><h2>Access created</h2><p>Permission is ready. No client has connected just because this profile was created.</p><p>Save its private client credential now. It is shown once and is separate from your Home Assistant credentials.</p><code>${this.secret}</code><div class="actions"><button ?disabled=${this.busy} @click=${() => { void this.copyCredential(); }}>Copy credential</button><button ?disabled=${this.busy} @click=${() => { this.secret = ''; this.secretScope = undefined; }}>I have saved it</button></div>${this.clientGuide(this.secretScope?.resources ?? [], this.secretScope?.capabilities ?? [])}</section>`;
  }
  private access() {
    const choices = this.operationChoices(); const editing = this.editMember;
    return html`<p class="eyebrow">Useful access, on your terms</p><h1>Who may do what?</h1><p class="page-description">Give each person, agent, machine or device its own resources, operations and expiry. An observer can read without controlling anything.</p><p class="hint">These are service-client access profiles. A trusted client must be connected separately; creating one does not pair a phone or add a native HA user.</p>
      ${this.secret ? this.accessCreated() : nothing}
      <form class="card access-form" @submit=${(event: Event) => { event.preventDefault(); const form = event.currentTarget as HTMLFormElement; if (!form.reportValidity()) return; const data = new FormData(form); void this.work(async () => { const limits = this.grantCapabilities.includes('ha.media.volume') ? { maxVolumePct: Number(this.volumeLimit) } : {}; const scope = { hours: Number(data.get('hours')), resources: this.grantResources, capabilities: this.grantCapabilities, limits }; if (editing) { await this.api('access/update', { id: editing.id, ...scope }); this.feedback = 'Access updated. Its existing client credential still works with the new scope.'; } else { const result = await this.api('access', { name: String(data.get('name')), kind: String(data.get('kind')), ...scope }); this.secret = result.credential; this.secretScope = { resources: this.status!.resources.filter(resource => scope.resources.includes(resource.id)), capabilities: [...scope.capabilities] }; } this.cancelEdit(); form.reset(); }); }}>
        <h2>${editing ? `Update access for ${editing.name}` : 'Create an access profile'}</h2>${editing ? html`<p>Review the resources and operations, then choose how long the revised access lasts. Its client credential is preserved.</p>` : html`<label class="field">Give it a familiar name<input name="name" placeholder="Household observer or media helper" maxlength="80" required></label>`}
        <div class="ranges">${!editing ? html`<label class="field">Who or what is it?<select name="kind"><option value="agent">AI agent</option><option value="machine">Computer or controller</option><option value="device">Device</option><option value="service">Service</option><option value="person">Person using a service client</option></select></label>` : nothing}<label class="field">Access lasts<select name="hours"><option value="24">24 hours</option><option value="168">7 days</option><option value="720">30 days</option><option value="1">1 hour</option></select></label></div>
        <fieldset><legend>1. Choose its resources</legend><p class="hint">Only resources you already shared appear here.</p><div class="scope">${this.status!.resources.map(r => html`<label class="pick"><input type="checkbox" aria-label=${`Allow ${r.name}`} .checked=${this.grantResources.includes(r.id)} ?disabled=${this.busy} @change=${(e: Event) => { this.grantResources = this.toggle(this.grantResources, r.id, (e.target as HTMLInputElement).checked); const supported = new Set(this.operationChoices().map(op => op.capability)); this.grantCapabilities = this.grantCapabilities.filter(cap => supported.has(cap)); this.template = 'custom'; }}><span><strong>${r.name}</strong><br><small>${kindLabel(r.kind)}</small></span></label>`)}</div></fieldset>
        <fieldset><legend>2. Choose its operations</legend><p class="hint">Start with a template or select exactly what it may request. Review the selected checkboxes before saving.</p><div class="actions">${[['observer', 'Read-only observer'], ['lighting', 'Lighting helper'], ['media', 'Media helper'], ['custom', 'Custom']].map(([value, label]) => html`<button type="button" ?disabled=${this.busy || !this.grantResources.length} aria-pressed=${this.template === value} @click=${() => this.chooseTemplate(value!)}>${label}</button>`)}</div>
          ${choices.length ? choices.map(op => html`<label class="pick"><input type="checkbox" aria-label=${`Permit ${op.label}`} .checked=${this.grantCapabilities.includes(op.capability)} ?disabled=${this.busy} @change=${(e: Event) => { const checked = (e.target as HTMLInputElement).checked; this.grantCapabilities = this.toggle(this.grantCapabilities, op.capability, checked); if (op.capability === 'ha.media.volume' && checked && !this.volumeLimit) this.volumeLimit = '40'; this.template = 'custom'; }}><span><strong>${op.label}</strong><br><small>${op.capability === readCapability ? 'Read a curated state snapshot. No device command.' : 'May operate compatible selected resources.'}</small></span></label>`) : html`<p class="empty">Choose resources first to see their available operations.</p>`}</fieldset>
        ${this.grantCapabilities.includes('ha.media.volume') ? html`<fieldset><legend>3. Set a useful volume limit</legend><label class="field">Maximum volume %<input name="maxVolumePct" type="number" min="0" max="100" step="1" .value=${this.volumeLimit} @input=${(event: Event) => { this.volumeLimit = (event.target as HTMLInputElement).value; }} required></label><p class="hint">Every delegated volume request must stay at or below this cap. A limit of 100 permits the device’s full volume range. This does not change your normal HA controls.</p></fieldset>` : nothing}
        <div class="scope-summary"><p>This profile may request <strong>${this.grantCapabilities.length} operations</strong> on <strong>${this.grantResources.length} selected resources</strong>, only where that operation is supported. All other operations are refused.${this.grantCapabilities.includes('ha.media.volume') ? html` Volume is limited to <strong>${this.volumeLimit || '—'}%</strong>.` : nothing}</p><p class="hint">Each selected operation applies to every compatible selected resource. Use separate profiles when different devices need different operation rules. Access ends after the duration selected above.</p></div><button class="primary" ?disabled=${this.busy || !this.grantResources.length || !this.grantCapabilities.length}>${editing ? 'Save access changes' : 'Create limited access'}</button>${editing ? html`<button type="button" ?disabled=${this.busy} @click=${() => this.cancelEdit()}>Cancel editing</button>` : nothing}
      </form><h2>Existing access</h2>${this.status!.members.map(member => this.memberCard(member))}`;
  }
  private memberCard(member: Member) {
    const labels = new Map(this.status!.resources.flatMap(r => r.operations).map(op => [op.capability, op.label]));
    const state = accessState(member), revoked = state === 'Access revoked', expired = state === 'Access expired';
    return html`<article class="card"><div class="row"><div><h3>${member.name}</h3><small>${member.kind} · ${state} · ${member.resources.length} resources</small><p class="hint">${usageLabel(member)}</p></div>${member.nativeUser ? html`<span class="badge">HA administrator</span>` : html`<div class="actions"><button ?disabled=${this.busy || revoked} @click=${() => this.beginEdit(member)}>${expired ? 'Renew access' : 'Edit access'}</button><button ?disabled=${this.busy || !member.enabled && member.connection?.state !== 'needs_review'} @click=${() => { void this.work(async () => { await this.api('revoke', { id: member.id }); }); }}>End access</button></div>`}</div>
      ${revoked && !member.nativeUser ? html`<p class="hint">This credential stays revoked. Create a new profile if the participant needs access again.</p>` : nothing}${member.legacyLimited ? html`<p class="notice">Original access scope preserved. This profile has not gained observation or new controls from this update. Review access explicitly to add a broader role.</p>` : nothing}${member.limits?.maxVolumePct !== undefined ? html`<p><span class="badge">Maximum volume: ${member.limits.maxVolumePct}%</span></p>` : nothing}<details><summary>What this profile can request</summary><p>${member.capabilities?.map(cap => labels.get(cap) ?? cap).join(' · ') || 'No operations granted'}</p>${member.limits?.maxVolumePct === undefined && member.capabilities.includes('ha.media.volume') ? html`<p class="hint">No extra profile volume cap; the device’s full range is permitted.</p>` : nothing}<p class="hint">Expires ${new Date(member.expiresAt).toLocaleString()}. ${member.nativeUser ? 'Your active native HA administrator role is checked for each request.' : 'Its credential proves possession of this profile, not the identity of physical hardware.'}</p></details>${!member.nativeUser && !revoked ? this.clientGuide(this.status!.resources.filter(resource => member.resources.includes(resource.id)), member.capabilities) : nothing}</article>`;
  }
  private beginJob() {
    if (!this.jobDraft) { this.jobStep = 1; this.jobCreated = ''; this.jobResource = ''; this.jobSearch = ''; this.jobCapabilities = []; this.jobIncludeResource = false; this.jobBrowseAll = false; this.jobName = purposes.find(p => p.id === this.jobPurpose)!.name; }
    this.jobDraft = true; this.navigate('wizard'); this.focusHeading();
  }
  private focusHeading() { void this.updateComplete.then(() => this.renderRoot.querySelector<HTMLElement>('main h1')?.focus()); }
  private stepJob(step: number) { this.jobStep = step; this.message = ''; this.focusHeading(); }
  private eligibleJobResources() { return this.catalog.filter(resource => purposeMatches(this.jobPurpose, resource)); }
  private chosenJobResource() { return this.catalog.find(resource => resource.id === this.jobResource); }
  private jobState(job: Job) {
    return ({ waiting_for_integration: 'Finish connecting', ready_to_test: 'Ready for a connection test', verified: 'Connection tested', expired: 'Access expired', revoked: 'Access ended' })[job.connectionState];
  }
  private jobCard(job: Job) {
    const resource = this.catalog.find(r => job.resources.includes(r.id));
    const ended = ['expired', 'revoked'].includes(job.connectionState);
    const snapshot = job.purpose === 'observer' ? job.lastTest?.observation : undefined;
    const unit = typeof snapshot?.attributes['unit_of_measurement'] === 'string' ? snapshot.attributes['unit_of_measurement'].slice(0, 40) : '';
    return html`<article class="card job-card"><div class="row"><div><p class="eyebrow">${job.purpose === 'observer' ? 'Read-only observer' : 'Media helper'}</p><h2>${job.name}</h2></div><span class="badge ${job.connectionState === 'verified' ? '' : 'warning'}">${this.jobState(job)}</span></div>
      <p>${resource?.name ?? 'Previously selected device'}${resource?.areaName || resource?.area ? html` · ${resource.areaName || resource.area}` : nothing}</p>
      ${snapshot ? html`<section class="job-snapshot" aria-label="Last observed measurement"><strong>${stateLabel(snapshot.state)}${unit ? html` ${unit}` : nothing}</strong><p>Observed ${new Date(snapshot.observedAt).toLocaleString()} · a snapshot, not a live reading.</p><div class="actions">${!ended ? html`<button ?disabled=${this.busy || !!this.verifyingJob} @click=${() => this.requestVerification(job, true)}>${this.verifyingJob === job.id ? 'Refreshing…' : 'Refresh reading'}</button>` : nothing}<button @click=${() => { this.outcome = job.lastTest; this.navigate('activity'); }}>View result</button></div></section>` : nothing}
      <p>${job.purpose === 'observer' ? 'Can read its current status. Cannot change devices.' : html`Selected media operations only.${job.limits.maxVolumePct !== undefined ? html` Volume up to <strong>${job.limits.maxVolumePct}%</strong>.` : nothing}`}</p>
      <p class="hint">${job.expiresAt ? `Access ends ${new Date(job.expiresAt).toLocaleString()}. ` : nothing}${job.lastVerifiedAt ? `Connection tested ${new Date(job.lastVerifiedAt).toLocaleString()}.` : 'Permission is prepared; a real connection test is still needed.'} This does not change other Home Assistant controls.</p>
      <div class="actions">${!ended ? html`<button class="primary" @click=${() => this.openJob(job)}> ${job.connectionState === 'verified' ? 'Connection details' : 'Continue setup'}</button>${job.connectionState === 'verified' ? html`<a class="button-link" href="/config/automation/dashboard" target="_blank" rel="noopener noreferrer">Open automations</a>` : nothing}<button @click=${() => { this.nativeEditId = job.id; this.editHours = String(job.hours); this.editVolume = String(job.limits.maxVolumePct ?? 40); this.navigate('jobedit'); this.focusHeading(); }}>Edit limits</button><button ?disabled=${this.busy} @click=${() => { void this.work(async () => { await this.api('jobs/revoke', { id: job.id }); }); }}>End this job</button>` : html`<button @click=${() => { this.beginJob(); }}>${this.jobDraft ? 'Resume setup' : 'Create a new job'}</button>`}</div>
      <details><summary>What this connection represents</summary><p>This is a separately scoped Home Assistant workflow connection. The workflow using it stays in Home Assistant. It is not a paired phone or proof of a physical device’s identity.</p><p>Permitted operations: ${job.capabilities.map(capability => resource?.operations.find(op => op.capability === capability)?.label ?? capability).join(' · ')}</p></details></article>`;
  }
  private openJob(job: Job) { this.openJobId = job.id; this.navigate('jobconnect'); this.focusHeading(); }
  private connectionView() {
    const job = this.status!.jobs?.find(item => item.id === this.openJobId);
    return html`<p class="eyebrow">Connect & verify</p><h1 tabindex="-1">${job?.name ?? 'Connection unavailable'}</h1>${job ? this.connectJob(job) : html`<p>This job is no longer available.</p>`}<button @click=${() => this.navigate('jobs')}>Back to jobs</button>`;
  }
  private editJobView() {
    const job = this.status!.jobs?.find(item => item.id === this.nativeEditId);
    if (!job) return html`<h1 tabindex="-1">This job is no longer available</h1><button @click=${() => this.navigate('jobs')}>Back to jobs</button>`;
    const resource = this.catalog.find(item => job.resources.includes(item.id));
    const invalidVolume = job.capabilities.includes('ha.media.volume') && (this.editVolume.trim() === '' || !Number.isInteger(Number(this.editVolume)) || Number(this.editVolume) < 0 || Number(this.editVolume) > 100);
    return html`<p class="eyebrow">Review a job</p><h1 tabindex="-1">Limits for ${job.name}</h1><section class="card"><p><strong>${resource?.name ?? 'Previously selected device'}</strong></p><p>Its target and permitted operations stay the same. Saving replaces the expiry and requires a new connection test.</p>
      ${job.capabilities.includes('ha.media.volume') ? html`<label class="field">Revised maximum volume %<input type="number" min="0" max="100" step="1" .value=${this.editVolume} @input=${(event: Event) => { this.editVolume = (event.target as HTMLInputElement).value; }}></label>` : nothing}
      <label class="field">Access from now<select aria-label="Access from now" .value=${this.editHours} @change=${(event: Event) => { this.editHours = (event.target as HTMLSelectElement).value; }}><option value="1">1 hour</option><option value="24">24 hours</option><option value="168">7 days</option><option value="720">30 days</option></select></label>
      <div class="actions"><button class="primary" ?disabled=${this.busy || invalidVolume} @click=${() => { void this.work(async () => { await this.api('access/update', { id: job.memberId, resources: job.resources, capabilities: job.capabilities, hours: Number(this.editHours), limits: job.capabilities.includes('ha.media.volume') ? { maxVolumePct: Number(this.editVolume) } : {} }); this.feedback = 'Limits updated. The existing integration credential is preserved. Test its connection again.'; this.navigate('jobs'); }); }}>Save job limits</button><button @click=${() => this.navigate('jobs')}>Cancel</button></div></section>`;
  }
  private jobsView() {
    const jobs = this.status!.jobs ?? [];
    return html`<div class="row"><div><p class="eyebrow">Jobs & access</p><h1 tabindex="-1">Useful jobs, clear limits.</h1></div><button class="primary" @click=${() => this.beginJob()}>${this.jobDraft ? 'Resume setup' : 'Give something a job'}</button></div>
      <p class="page-description">Use your existing Home Assistant workflows. Each connection gets selected devices, permitted operations and an expiry.</p>
      ${jobs.length ? jobs.map(job => this.jobCard(job)) : html`<section class="card"><h2>Start with one useful task</h2><p>Read a measurement, or let a media helper operate one speaker with a volume ceiling. We’ll guide you through the connection and its first request.</p><button @click=${() => this.beginJob()}>Choose a task</button></section>`}
      <details class="card"><summary>People, agents and other connections</summary><p>The guided path currently connects Home Assistant workflows. Direct phone invitations and external-agent pairing are not available here yet. Existing service-client access stays available in Advanced → Access.</p></details>`;
  }
  private wizard() {
    const selected = this.chosenJobResource(); const resources = this.eligibleJobResources().filter(resource => this.jobPurpose !== 'observer' || this.jobBrowseAll || suggestedMeasurement(resource)); const term = this.jobSearch.trim().toLocaleLowerCase();
    const matches = resources.filter(resource => [resource.name, resource.deviceName, resource.areaName, resource.area].filter(Boolean).join(' ').toLocaleLowerCase().includes(term));
    const steps = ['Choose a task', 'Choose its connection', 'Choose a device', 'Set its limits', 'Connect & verify'];
    const job = this.status!.jobs?.find(item => item.id === this.jobCreated);
    const needsEligibility = this.status!.ready && !!selected && !this.status!.resources.some(resource => resource.id === selected.id);
    return html`<p class="eyebrow">Step ${this.jobStep} of 5</p><h1 tabindex="-1">${steps[this.jobStep - 1]}</h1><ol class="steps" aria-label="Setup progress">${steps.map((title, index) => html`<li aria-current=${index + 1 === this.jobStep ? 'step' : 'false'}>${index + 1}. ${title}</li>`)}</ol>
      ${this.jobStep === 1 ? html`<p>What would you like something to help with?</p><div class="grid">${purposes.map(purpose => html`<button class="card purpose" aria-pressed=${this.jobPurpose === purpose.id} @click=${() => { this.jobPurpose = purpose.id; this.jobName = purpose.name; this.jobResource = ''; this.jobCapabilities = []; this.jobIncludeResource = false; this.jobBrowseAll = false; }}><strong>${purpose.title}</strong><span>${purpose.description}</span></button>`)}</div><p class="hint">Your current Home Assistant controls and automations keep working.</p>` : nothing}
      ${this.jobStep === 2 ? html`<section class="card"><h2>Use an existing Home Assistant workflow</h2><p>Connect once, then choose this job in the native Home Assistant automation editor. No new phone app, public port or general Home Assistant token is needed.</p><label class="field">Job name<input maxlength="80" .value=${this.jobName} @input=${(event: Event) => { this.jobName = (event.target as HTMLInputElement).value; }} placeholder="For example, home energy observer"></label><p class="hint">This connection has its own limited identity. It does not give every automation a different identity automatically.</p></section>` : nothing}
      ${this.jobStep === 3 ? html`<p>Choose one ${this.jobPurpose === 'media' ? 'speaker or media player' : 'control or measurement'} for this job. Create another job for another target.</p><label class="field">Find a room or device<input type="search" .value=${this.jobSearch} @input=${(event: Event) => { this.jobSearch = (event.target as HTMLInputElement).value; }} placeholder="Search your Home Assistant names"></label>
        ${this.jobPurpose === 'observer' ? html`<div class="row picker-intro"><div><h2>${this.jobBrowseAll ? 'All readable states' : 'Suggested measurements'}</h2><p class="hint">${this.jobBrowseAll ? 'Search every compatible readable entity, including device status and integration states.' : 'Start with sensors and status measurements. Choose a room, or search for a measurement.'}</p></div><button aria-pressed=${this.jobBrowseAll} @click=${() => { this.jobBrowseAll = !this.jobBrowseAll; if (!this.jobBrowseAll && selected && !suggestedMeasurement(selected)) { this.jobResource = ''; this.jobCapabilities = []; this.jobIncludeResource = false; } }}>${this.jobBrowseAll ? 'Show suggested measurements' : 'Browse all readable states'}</button></div>` : nothing}
        ${this.status!.ready ? html`<details class="eligibility-help"><summary>A device is not yet eligible for Mesh?</summary><p>You can select it here and explicitly confirm only that target on the review step. Existing participant permissions stay the same.</p><button @click=${() => this.beginSharing('wizard')}>Review all eligible devices</button></details>` : nothing}
        <p class="count">${matches.length} ${this.jobPurpose === 'media' ? 'media targets' : 'measurements or states'} · one target per job</p><div class="room-list">${groupHome(matches).map(room => html`<details class="room-picker" ?open=${!!term || this.jobPurpose === 'media' || room.devices.some(device => device.resources.some(resource => resource.id === this.jobResource))}><summary><h2>${room.name}</h2><span>${room.devices.length} ${room.devices.length === 1 ? 'device' : 'devices'}</span></summary>${room.devices.map(device => html`<details class="device-picker" ?open=${!!term || device.resources.length <= 2 || device.resources.some(resource => resource.id === this.jobResource)}><summary><h3>${device.name}</h3><span>${device.resources.length} ${device.resources.length === 1 ? 'target' : 'targets'}</span></summary>${device.resources.map(resource => html`<label class="pick"><input type="radio" name="job-resource" aria-label=${`Choose ${resource.name}`} .checked=${this.jobResource === resource.id} @change=${() => { this.jobResource = resource.id; this.jobIncludeResource = false; this.jobCapabilities = purposeCapabilities(this.jobPurpose, [resource]); }}><span><strong>${resource.name}</strong><br><small>${kindLabel(resource.kind)}${this.status!.ready && !this.status!.resources.some(item => item.id === resource.id) ? ' · Not yet eligible for Mesh' : ''}${!resource.available ? ' · Currently unavailable' : ''}</small></span></label>`)}</details>`)}</details>`)}</div>
        ${!matches.length ? html`<p class="empty">No compatible Home Assistant targets match. Try another search.${this.jobPurpose === 'observer' && !this.jobBrowseAll ? ' Choose Browse all readable states to include other device and integration status.' : ' Try another room or Home Assistant name.'}</p>` : nothing}` : nothing}
      ${this.jobStep === 4 ? html`<section class="card"><h2>${selected?.name}</h2><p>Choose exactly what this connection may request.</p>${selected ? purposeCapabilities(this.jobPurpose, [selected]).map(capability => html`<label class="pick"><input type="checkbox" aria-label=${`Allow job ${selected.operations.find(op => op.capability === capability)?.label}`} ?disabled=${capability === readCapability} .checked=${this.jobCapabilities.includes(capability)} @change=${(event: Event) => { this.jobCapabilities = this.toggle(this.jobCapabilities, capability, (event.target as HTMLInputElement).checked); }}><span>${selected.operations.find(op => op.capability === capability)?.label}</span></label>`) : nothing}
        ${this.jobCapabilities.includes('ha.media.volume') ? html`<label class="field">Maximum job volume %<input type="number" min="0" max="100" step="1" .value=${this.jobVolume} @input=${(event: Event) => { this.jobVolume = (event.target as HTMLInputElement).value; }}></label>` : nothing}
        <label class="field">Job access lasts<select aria-label="Job access lasts" .value=${this.jobHours} @change=${(event: Event) => { this.jobHours = (event.target as HTMLSelectElement).value; }}><option value="1">1 hour</option><option value="24">24 hours</option><option value="168">7 days</option><option value="720">30 days</option></select></label><p class="hint">Expiry ends new requests through this connection. Other Home Assistant paths keep their existing permissions.</p></section>` : nothing}
      ${this.jobStep === 5 ? job ? this.connectJob(job) : html`<section class="card"><h2>Review ${this.jobName}</h2><dl class="review"><dt>Connection</dt><dd>Home Assistant workflow</dd><dt>Target</dt><dd>${selected?.name}</dd><dt>May request</dt><dd>${this.jobCapabilities.map(capability => selected?.operations.find(op => op.capability === capability)?.label).join(' · ')}</dd>${this.jobCapabilities.includes('ha.media.volume') ? html`<dt>Maximum volume</dt><dd>${this.jobVolume}%</dd>` : nothing}<dt>Access lasts</dt><dd>${Number(this.jobHours) === 1 ? '1 hour' : Number(this.jobHours) === 24 ? '24 hours' : `${Number(this.jobHours) / 24} days`}</dd></dl><p>No other targets or operations are included. This does not change the device now.</p>${needsEligibility ? html`<label class="pick notice"><input type="checkbox" aria-label=${`Make ${selected!.name} eligible and give this job the reviewed access`} .checked=${this.jobIncludeResource} @change=${(event: Event) => { this.jobIncludeResource = (event.target as HTMLInputElement).checked; }}><span>Make <strong>${selected!.name}</strong> eligible and give this job the reviewed access.<br><small>This adds only this target to Mesh eligibility. Other excluded devices and existing participant permissions stay the same.</small></span></label>` : nothing}<p class="hint">Home Assistant system workflows using this connection may run this job. Native user calls are limited to the owner who creates it; this is not a separate identity for every automation.</p><button class="primary" ?disabled=${this.busy || needsEligibility && !this.jobIncludeResource} @click=${() => { void this.work(async () => { const result = await this.api('jobs', { name: this.jobName.trim(), purpose: this.jobPurpose, resources: [this.jobResource], capabilities: this.jobCapabilities, hours: Number(this.jobHours), ...(needsEligibility && this.jobIncludeResource ? { includeResource: true } : {}), limits: this.jobCapabilities.includes('ha.media.volume') ? { maxVolumePct: Number(this.jobVolume) } : {} }); this.jobCreated = result.job.id; this.jobDraft = false; }); }}>Create job and connect</button></section>` : nothing}
      <div class="wizard-actions">${this.jobStep > 1 && !job ? html`<button ?disabled=${this.busy} @click=${() => this.stepJob(this.jobStep - 1)}>Back</button>` : nothing}${this.jobStep < 5 ? html`<button class="primary" ?disabled=${this.busy || this.jobStep === 2 && !this.jobName.trim() || this.jobStep === 3 && !selected || this.jobStep === 4 && (!this.jobCapabilities.length || this.jobPurpose === 'media' && !this.jobCapabilities.some(capability => capability !== readCapability) || this.jobCapabilities.includes('ha.media.volume') && (this.jobVolume.trim() === '' || !Number.isInteger(Number(this.jobVolume)) || Number(this.jobVolume) < 0 || Number(this.jobVolume) > 100))} @click=${() => this.stepJob(this.jobStep + 1)}>Continue</button>` : nothing}<button @click=${() => this.navigate('jobs')}>${job ? 'Back to jobs' : 'Finish later'}</button></div>`;
  }
  private connectJob(job: Job) {
    const ended = ['expired', 'revoked'].includes(job.connectionState); const connected = job.connectionState !== 'waiting_for_integration' && !ended;
    const nativeActions = [{ capability: readCapability, label: 'Observe status', action: 'genesismesh.observe' }, { capability: 'ha.media.volume', label: 'Set volume', action: 'genesismesh.set_volume' }, { capability: 'ha.media.transport', label: 'Control playback', action: 'genesismesh.playback' }].filter(action => job.capabilities.includes(action.capability));
    return html`<section class="card"><h2>${job.name}</h2><span class="badge">${this.jobState(job)}</span>${ended ? html`<p>This job’s access has ended. Create a new job or review its access from Advanced.</p>` : html`
      <ol class="connection-checklist"><li><strong>Permission prepared</strong><p>Only the target, operations and limits you reviewed are included.</p></li><li><strong>${connected ? 'Integration pairing accepted' : 'Connect the Home Assistant integration'}</strong><p>${connected ? 'The integration has claimed this job’s pairing code. Verify a real request next; pairing alone is not a completed connection test.' : 'The companion integration makes this job available in your existing Home Assistant workflows.'}</p>${!connected ? html`<details><summary>First time connecting this Home Assistant?</summary><p>If Genesis Mesh is not listed in Add integration, install its companion integration once. Future updates use the same connection and versioned package.</p><a class="button-link" href="./genesismesh-integration.zip" download>Download the Home Assistant integration</a><ol><li>Extract the package into your Home Assistant configuration folder. It contains custom_components/genesismesh.</li><li>Restart Home Assistant Core, then return here.</li><li>Generate a connection code and choose Open Home Assistant integration setup.</li></ol><p class="hint">The integration is custom software; it is not installed by adding the app repository. Keep this code private and enter it only into your own HA integration.</p></details><button ?disabled=${this.busy} @click=${() => { void this.work(async () => { const result = await this.api('jobs/pair', { id: job.id }); this.pairCode = result.code; this.pairExpiry = result.expiresAt; this.pairingJob = job.id; }); }}>Get a connection code</button>${this.pairCode && this.pairingJob === job.id ? html`<div class="notice"><p>Enter this single-use code in the Genesis Mesh integration setup:</p><p class="pair-code">${this.pairCode}</p><button @click=${() => { void this.copyPairingCode(); }}>Copy connection code</button><p class="hint">Expires ${new Date(this.pairExpiry).toLocaleTimeString()}. Keep it private. The integration stores the resulting credential for you.</p><a class="button-link" href=${this.status!.companion?.setupUrl ?? '/config/integrations/dashboard/add?domain=genesismesh'} target="_blank" rel="noopener noreferrer">Open Home Assistant integration setup</a><p class="hint">Setup opens in another tab. After you finish there, return to this tab and choose Check connection, then Test this connection.</p></div>` : nothing}<button @click=${() => { void this.refresh(); }}>Check connection</button>` : nothing}</li>
      <li><strong>${job.connectionState === 'verified' ? 'First request verified' : 'Verify its first request'}</strong><p>${job.connectionState === 'verified' ? `A real request through the companion connection was verified${job.lastVerifiedAt ? ` at ${new Date(job.lastVerifiedAt).toLocaleString()}` : ''}. This is a past test, not an always-online indicator.` : 'Queue a safe connection test. The integration performs it under this job’s identity; this page does not impersonate the participant.'}</p><button class="primary" ?disabled=${this.busy || !connected || !!this.verifyingJob} @click=${() => this.requestVerification(job)}>${this.verifyingJob === job.id ? 'Waiting for its request…' : job.connectionState === 'verified' ? 'Test connection again' : 'Test this connection'}</button></li></ol>
      ${connected ? html`<details><summary>Reconnect or replace the integration</summary><p>Generate a replacement code only if this job’s integration entry was removed or needs replacing. Its previous integration credential will stop working.</p><button ?disabled=${this.busy} @click=${() => { void this.work(async () => { const result = await this.api('jobs/pair', { id: job.id }); this.pairCode = result.code; this.pairExpiry = result.expiresAt; this.pairingJob = job.id; }); }}>Replace this connection</button></details>` : nothing}${job.lastTest ? html`<p>${commandLabel(job.lastTest.commandState)} ${recordLabel(job.lastTest.evidenceState)}</p>` : nothing}${job.connectionState === 'verified' ? html`<section class="notice success"><h3>Ready for your Home Assistant workflow</h3><p>In the native automation editor, add a Genesis Mesh action and choose this connection. Available actions for this job: <strong>${nativeActions.map(action => action.label).join(' · ')}</strong>. Your triggers and schedule stay in Home Assistant.</p><dl class="review"><dt>Job</dt><dd>${job.name}</dd></dl><a class="button-link" href="/config/automation/dashboard" target="_blank" rel="noopener noreferrer">Open Home Assistant automations</a><p class="hint">Opens your existing automation editor in another tab. Add the Genesis Mesh action to the workflow you choose; nothing is created or enabled automatically.</p><details><summary>Action reference</summary><code>${nativeActions.map(action => action.action).join('\n')}</code><p>Choose this job’s integration connection in the native selector. Each connection is paired to one job; action fields cannot choose a broader identity or target.</p><code>${job.id}</code></details></section>` : nothing}`}</section>`;
  }
  private requestVerification(job: Job, reading = false) {
    this.verificationIsReading = reading;
    void this.work(async () => { this.verifyBaseline = job.lastTest?.id ?? ''; await this.api('jobs/test', { id: job.id }); this.verifyingJob = job.id; this.feedback = reading ? 'Waiting for a new observation from this job’s integration. The earlier snapshot stays visible.' : 'Waiting for the integration to perform the connection test. No device control is sent.'; this.pollVerification(job.id, 0); });
  }
  private pollVerification(id: string, attempt: number) {
    if (this.verifyTimer) clearTimeout(this.verifyTimer);
    this.verifyTimer = setTimeout(() => { void (async () => { try { await this.load(); const job = this.status!.jobs?.find(item => item.id === id); if (job?.connectionState === 'verified' && !job.verificationPending && job.lastTest?.id !== this.verifyBaseline) { this.verifyingJob = ''; this.feedback = this.verificationIsReading ? 'Updated reading received from this job’s integration connection.' : 'Connection verified by the participant’s real request.'; return; } if (attempt >= 19 || !job || ['revoked', 'expired'].includes(job.connectionState)) { this.verifyingJob = ''; this.message = this.verificationIsReading ? 'The reading has not refreshed. The earlier snapshot is still shown with its original time. Check the integration before trying again.' : 'The connection test has not completed. Check the integration in Home Assistant, then test again. No device control was sent.'; return; } this.pollVerification(id, attempt + 1); } catch { this.verifyingJob = ''; this.message = 'Could not check the test result. Review Activity and the integration before trying again.'; } })(); }, 1500);
  }
  private homeView() {
    const jobs = this.status!.jobs ?? [];
    return html`<div class="row"><div><p class="eyebrow">Your existing home. Useful help.</p><h1 tabindex="-1">${jobs.length ? 'Your useful connections' : 'What would you like help with?'}</h1><p class="page-description">${jobs.length ? 'Your jobs, their limits and the latest results from your existing Home Assistant.' : 'Give a Home Assistant workflow a useful job, with limits you choose. Your devices, automations and everyday controls stay in Home Assistant.'}</p></div>${jobs.length ? html`<button class="primary" @click=${() => this.beginJob()}>${this.jobDraft ? 'Resume setup' : 'Give something a job'}</button>` : nothing}</div>
      ${jobs.length ? jobs.map(job => this.jobCard(job)) : html`<section class="card welcome"><h2>Start with one small job</h2><p>Read a home measurement, or let a media helper use a speaker below your volume limit. We’ll guide you from choosing the task to its first verified request.</p><button class="primary" @click=${() => this.beginJob()}>${this.jobDraft ? 'Resume setup' : 'Give something a job'}</button></section><p class="hint">No jobs yet. Discovering a device does not give anyone access to it.</p>`}
      <div class="grid"><section class="card"><h2>Your home is already here</h2><p>Browse the devices and measurements Home Assistant knows, grouped by room where available.</p><button @click=${() => this.navigate('devices')}>Explore devices</button></section><section class="card"><h2>See what happened</h2><p>Understand requests, refusals and signed records from these connections.</p><button @click=${() => this.navigate('activity')}>Review activity</button></section></div>`;
  }
  private observation(operation: Operation) {
    const observation = operation.observation;
    return observation ? html`<div class="notice success"><strong>Observed state: ${stateLabel(observation.state)}</strong><dl class="observation">${Object.entries(observation.attributes).map(([key, value]) => html`<dt>${key.replaceAll('_', ' ')}</dt><dd>${typeof value === 'string' ? value : JSON.stringify(value)}</dd>`)}</dl><small>Observed ${new Date(observation.observedAt).toLocaleString()}. A snapshot, not a guarantee of its current state.</small></div>` : nothing;
  }
  private result(operation: Operation) {
    return html`<section class="notice" role="status"><h2>${this.operationTitle(operation)}</h2><strong>${commandLabel(operation.commandState)}</strong>${['accepted', 'observed'].includes(operation.commandState) ? nothing : html`<p>${requestExplanation(operation)}</p>`}<p><span class="badge">${recordLabel(operation.evidenceState)}</span></p>${this.observation(operation)}<button @click=${() => { this.outcome = undefined; }}>Dismiss result</button></section>`;
  }
  private operationTitle(operation: Operation): string {
    if (operation.summary) return operation.summary;
    const label = this.catalog.flatMap(resource => resource.operations).find(option => option.capability === operation.capability)?.label;
    const values = Object.entries(operation.parameters ?? {}).map(([key, value]) => `${key.replaceAll('_', ' ')}: ${String(value).slice(0, 100)}`).join(', ');
    return `${label ?? (operation.capability === readCapability ? 'Read current status' : 'Earlier request')}${values ? ` · ${values}` : ''}`;
  }
  private activity() {
    return html`<p class="eyebrow">Decisions & results</p><h1>Requests with a record.</h1><p>Latest 50 requests through this app. Observations, admitted commands and physical outcomes are different kinds of evidence.</p><section class="card">${this.status!.activity.length ? this.status!.activity.map(operation => html`<article class="operation"><h2>${this.operationTitle(operation)}</h2><strong>${commandLabel(operation.commandState)}</strong><p>${this.status!.resources.find(r => r.id === operation.resourceId)?.name ?? 'Previously shared resource'} · requested by ${this.status!.members.find(m => m.id === operation.subjectId)?.name ?? 'Earlier participant'}<br><small>${new Date(operation.createdAt).toLocaleString()}</small></p>${['accepted', 'observed'].includes(operation.commandState) ? nothing : html`<p>${requestExplanation(operation)}</p>`}<span class="badge">${recordLabel(operation.evidenceState)}</span>${this.observation(operation)}<details><summary>Technical reference</summary><code>${operation.id}</code><p>${operation.reason}${operation.policyFailures.length ? ` · ${operation.policyFailures.join(', ')}` : ''}</p></details></article>`) : html`<p class="empty">No requests yet. Observe a shared entity from Devices to see the decision and result here.</p>`}</section>`;
  }
  override render() {
    return html`<header><div><img src="./logo.svg" alt="Genesis Mesh"><strong>Genesis Mesh<br><small>Home Assistant</small></strong></div><span class="badge">Experimental preview</span></header>
      ${this.message ? html`<div class="notice" role="alert">${this.message}<p>After a connection error during a control request, review Activity and the device before another request.</p><button ?disabled=${this.busy} @click=${() => { void this.refresh(); }}>Refresh connection</button></div>` : nothing}
      ${this.feedback ? html`<div class="notice success" role="status"><p>${this.feedback}</p></div>` : nothing}${this.status ? html`<nav aria-label="Genesis Mesh">${[['home', 'Home'], ['jobs', 'Jobs'], ['devices', 'Devices'], ['activity', 'Activity']].map(([page, label]) => html`<button aria-current=${this.page === page ? 'page' : 'false'} @click=${() => this.navigate(page!)}>${label}</button>`)}</nav>${this.outcome ? this.result(this.outcome) : nothing}<main aria-busy=${this.busy}>${this.status.needsRecovery || this.page === 'setup' ? this.setup() : this.page === 'jobconnect' ? this.connectionView() : this.page === 'jobedit' ? this.editJobView() : this.page === 'wizard' ? this.wizard() : this.page === 'jobs' ? this.jobsView() : this.page === 'devices' ? this.devices() : this.page === 'access' ? this.access() : this.page === 'activity' ? this.activity() : this.homeView()}</main><details class="card advanced"><summary>Advanced</summary><p>Existing service-client access, sharing eligibility and diagnostics. The guided Jobs setup is the usual starting point.</p><div class="actions"><button @click=${() => this.navigate('access')}>Access</button><button @click=${() => this.beginSharing()}>${this.sharingDraft ? 'Resume sharing selection' : 'Change shared devices'}</button></div><p class="hint">${this.status.custody} Normal HA controls and vendor paths stay outside these jobs. Discovery does not enroll physical devices as Mesh participants.</p></details>` : html`<p role="status">${this.busy ? 'Connecting to your Home Assistant session…' : 'Open this app from Home Assistant with an administrator account.'}</p>`}
      <footer>Identity · Permission · Evidence. ${this.busy ? 'Working…' : ''}</footer>`;
  }
}
customElements.define('genesis-home', GenesisHome);
document.body.style.margin = '0'; document.body.style.background = '#f5f7f3';
